lemma tensorHom_comp_tensorHom {x x' x'' y y' y'' : FintypeGrpd.{u}}
    (f : x ⟶ x') (f' : x' ⟶ x'') (g : y ⟶ y') (g' : y' ⟶ y'') :
    (f ⊗ₘ g) ≫ (f' ⊗ₘ g') = (f ≫ f') ⊗ₘ (g ≫ g')

private lemma inversionSet_mul_swap_castSucc_succ_eq_of_le
    (σ : Equiv.Perm (Fin (n + 1))) (i : Fin n) (hi : σ i.castSucc < σ i.succ) :
    ℐ (σ * Ψ i) = Finset.image (Equiv.prodCongr (Ψ i) (Ψ i)) (ℐ σ) ∪ {(i.castSucc, i.succ)}

lemma tensorHom_comp_tensorHom {x x' x'' y y' y'' : J ⟶ K}
    (f : x ⟶ x') (f' : x' ⟶ x'') (g : y ⟶ y') (g' : y' ⟶ y'') :
    (f ⊗ₘ g) ≫ (f' ⊗ₘ g') = (f ≫ f') ⊗ₘ (g ≫ g')

lemma hom_eq_of_totEquivOfHom_eq {X X' : K → SList J} {f g : X ⟶ X'}
    (h : totEquivOfHom f = totEquivOfHom g) :
    f = g

@[local simp, local grind _=_] lemma whiskerLeft_comp (x : SList C) {y z t : SList C}
    (f : y ⟶ z) (g : z ⟶ t) :
    x ◁ (f ≫ g) = x ◁ f ≫ x ◁ g

@[local simp, local grind _=_] lemma comp_whiskerRight {x y z : SList C}
    (f : x ⟶ y) (g : y ⟶ z) {t : SList C} :
    (f ≫ g) ▷ t = f ▷ t ≫ g ▷ t

