private lemma cons_cons_hom_inv_id (u v : C) {l l' : SList C} (e : l ≅ l') :
  (u ::~ₘ (v ::~ₘ e.hom)) ≫ (u ::~ₘ (v ::~ₘ e.inv)) = 𝟙 _

@[reassoc (attr := local simp)]
